steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    {
      issues(first: 10, filter: { title: { contains: \"Retention Playbook\" } }) {
        nodes {
          id
          identifier
          title
          description
          team { name }
        }
      }
    }
    "
  }'
